  {"slug":"wordtune","pricing_details":"Free: 10 rewrites/day; Advanced $13.99/mo ($6.99/mo annual); Unlimited $19.99/mo ($9.99/mo annual); Teams from $15.99/user/mo; Enterprise custom.","tagline":"AI writing companion for rewriting, tone adjustment, and clarity improvements.","description":"Wordtune by AI21 Labs helps rewrite and refine existing text for clarity, tone, and fluency via browser extension and web editor. It focuses on improving drafts rather than generating long-form content from scratch."},
  {"slug":"sweep","status":"archived","website_url":"https://sweep.dev","pricing_model":"paid","pricing_details":"Archived: hosted Sweep shut down on April 9, 2026. The team open-sourced its model and moved to Datacurve AI.","tagline":"Archived JetBrains AI coding assistant from Sweep AI.","description":"Sweep was a JetBrains-focused AI autocomplete and in-IDE agent plugin. The company announced shutdown on April 9, 2026; users should choose active alternatives such as Windsurf plugins, GitHub Copilot, Cursor, or JetBrains AI."},
  {"slug":"agentgpt","status":"archived","website_url":"https://agentgpt.reworkd.ai","pricing_model":"freemium","pricing_details":"Archived: GitHub repo archived January 28, 2026. Hosted demo may still load but receives no updates.","tagline":"Archived browser-based autonomous-agent experiment from Reworkd.","description":"AgentGPT was an early browser agent that decomposed goals into task loops. Reworkd archived the project in January 2026 and pivoted to enterprise web-data products."},
