  {"slug":"composio","website_url":"https://composio.dev","pricing_model":"freemium","pricing_details":"Free tier: 20,000 standard tool calls/mo; paid from $29/mo (200K calls) and $229/mo (2M calls); enterprise MCP Gateway with SSO and RBAC.","tagline":"MCP gateway and integration layer connecting agents to 1,000+ toolkits with managed auth.","description":"Composio gives AI agents managed access to 1,000+ SaaS and developer toolkits through actions, triggers, OAuth, and an enterprise MCP Gateway with SSO, RBAC, audit logs, and observability."},
  {"slug":"sourcegraph-cody","website_url":"https://sourcegraph.com/cody","pricing_model":"enterprise","pricing_details":"Cody Free and Pro discontinued July 23, 2025; Cody remains enterprise-only (~$59/user/mo annual). Individuals directed to Sourcegraph Amp.","tagline":"Sourcegraph's enterprise-only AI coding assistant with deep code-graph context.","description":"Cody uses Sourcegraph code intelligence for chat, autocomplete, and edits across massive codebases. Since July 2025 it is enterprise-only; Sourcegraph replaced Cody Free/Pro with Amp for individuals."},
  {"slug":"moltbook","website_url":"https://www.moltbook.com","pricing_model":"free","pricing_details":"Free to observe; agent participation requires operator setup. Acquired by Meta in March 2026.","tagline":"Agent-only social network acquired by Meta for agent coordination research.","description":"Moltbook is a Reddit-like forum where verified AI agents post and humans observe. It launched in January 2026 and was acquired by Meta in March 2026 to inform Meta Superintelligence Labs agent-coordination work."},
  {"slug":"openclaw","website_url":"https://openclaw.ai","pricing_model":"open_source","pricing_details":"MIT-licensed open source; users pay only for chosen LLM APIs or local inference.","tagline":"Local-first personal AI assistant with multi-channel messaging, Canvas UI, and ClawHub skills.","description":"OpenClaw is a widely adopted open-source personal agent framework that runs on your devices and connects to WhatsApp, Telegram, Slack, Discord, Signal, iMessage, and 20+ channels with gateway-based multi-agent routing."},
  {"slug":"superagi","website_url":"https://superagi.com","pricing_model":"freemium","pricing_details":"Open-source framework is free to self-host; hosted cloud and commercial Work AI plans add paid credits.","tagline":"Open-source agent framework plus commercial Work AI platform for sales and marketing automation.","description":"SuperAGI spans an open-source autonomous-agent framework and a hosted commercial Work AI super-app for sales, marketing, and workflow automation."},
  {"slug":"haiper","status":"archived","website_url":"https://haiper.ai","pricing_model":"freemium","pricing_details":"Archived: consumer web app shut down February 2025; no active public pricing.","tagline":"Archived AI video generator (consumer app discontinued).","description":"Haiper shut down its public consumer video app in February 2025 after its founders joined Microsoft AI. Compare active alternatives such as Runway, Kling AI, Pika, or Google Flow."},
  {"slug":"udio","website_url":"https://www.udio.com","pricing_model":"freemium","pricing_details":"Free and paid Standard/Pro plans during 2026 transition; licensed Starstruck experience launching with label deals. Public downloads disabled.","tagline":"Licensed AI music platform pivoting from open generation to fan remixes.","description":"Udio is transitioning from open music generation toward a licensed product called Starstruck after settlements with major rightsholders. Public song downloads were removed in late 2025 while Udio builds licensed remix workflows."},
  {"slug":"julius-ai","website_url":"https://julius.ai","pricing_model":"freemium","pricing_details":"Free with daily credits; Plus $20/mo, Pro $45/mo, Max $200/mo, Ultra $500/mo, Business $450/mo. Enterprise custom.","tagline":"AI data agents for spreadsheets, notebooks, warehouses, and team analytics.","description":"Julius AI is a conversational data analysis platform where users upload files or connect warehouses, then ask questions in natural language to get charts, statistics, reports, and scheduled insights."},
  {"slug":"meshy","website_url":"https://www.meshy.ai","pricing_model":"freemium","pricing_details":"Free: 100 credits/mo. Pro $20/mo: 1,000 credits. Studio $60/mo: 4,000 credits and team workspace. Enterprise custom.","tagline":"Meshy 6 text- and image-to-3D generator with textures, rigging, and APIs.","description":"Meshy generates textured 3D models from text or images, centered on Meshy 6 workflows with preview and full-generation credit costs. Pro adds commercial ownership and API access."},
  {"slug":"arc-max","website_url":"https://arc.net/max","pricing_model":"freemium","pricing_details":"Opt-in AI features inside Arc Browser; Arc is in maintenance mode with security updates only since May 2025.","tagline":"Legacy Arc Browser AI features—maintenance mode; Dia is the successor.","description":"Arc Max bundled opt-in AI helpers inside Arc Browser. The Browser Company stopped active Arc development in May 2025 to focus on Dia, though Arc still receives Chromium security updates."},
  {"slug":"runway","website_url":"https://runwayml.com","pricing_model":"freemium","pricing_details":"Free: 125 one-time credits. Standard $12/mo annual: 625 credits/mo with Gen-4.5. Pro $28/mo: 2,250 credits, 4K. Unlimited $76/mo. Enterprise custom.","tagline":"Gen-4.5-powered AI video, image, and editing studio for creators.","description":"Runway is a creative AI platform for text- and image-to-video, video editing, generative fill, motion control, and studio workflows. Gen-4.5 is the flagship video model on paid plans as of 2026."},
  {"slug":"synthesia","website_url":"https://www.synthesia.io","pricing_model":"freemium","pricing_details":"Free Basic (~10 min/mo, watermarked). Starter $29/mo or $18/mo annual. Creator $89/mo or $64/mo annual with API. Enterprise custom.","tagline":"Enterprise avatar video platform with credits for training, dubbing, and agents.","description":"Synthesia lets teams create avatar-led videos from scripts for L&D, internal comms, sales, and localization. Plans use a shared credits pool for video generation, dubbing, and Synthesia 3.0 features."},
  {"slug":"descript","website_url":"https://www.descript.com","pricing_model":"freemium","pricing_details":"Free: 60 media min/mo and 100 one-time AI credits. Hobbyist $24/mo: 10 media hrs + 400 AI credits. Creator $35/mo: 30 hrs + 800 credits. Business $65/mo: 40 hrs + 1500 credits.","tagline":"Transcript-based video editor with Underlord AI, avatars, and dubbing.","description":"Descript edits audio and video by editing text transcripts, with AI tools for Studio Sound, filler-word removal, clips, captions, voice cloning, avatars, translation, and Underlord co-editing."},
  {"slug":"heygen","website_url":"https://www.heygen.com","pricing_model":"freemium","pricing_details":"Free: 3 videos/mo up to 1 min, 720p watermark. Creator $29/mo: 600 credits, 1080p. Pro from $49/mo. Business $149/mo + $20/seat with 1,500 credits, 4K.","tagline":"Credit-based AI avatar videos, translation, and Video Agent workflows.","description":"HeyGen creates avatar-led videos, translated lip-sync content, and prompt-based Video Agent projects for marketing, sales, and training. Paid plans revolve around monthly premium credits."},
  {"slug":"dall-e-3","website_url":"https://openai.com/dall-e-3","pricing_model":"freemium","pricing_details":"Legacy model: OpenAI deprecated DALL-E 2/3 API endpoints May 12, 2026. ChatGPT defaults to GPT Image models; API users should migrate to gpt-image-1 or gpt-image-2.","tagline":"Legacy OpenAI image model superseded by GPT Image in ChatGPT and API.","description":"DALL-E 3 was OpenAI's prior flagship text-to-image model. As of May 2026, OpenAI retired DALL-E API endpoints in favor of GPT Image models, so treat this listing as historical context."},
  {"slug":"clipdrop","website_url":"https://clipdrop.co","pricing_model":"freemium","pricing_details":"Free tools limited; standalone Clipdrop subscriptions remain at clipdrop.co alongside Jasper API access for business customers.","tagline":"Jasper-owned AI image editing suite still sold at clipdrop.co.","description":"Clipdrop provides background removal, cleanup, relighting, upscaling, and generative image edits. Jasper acquired Clipdrop in February 2024 and embeds its capabilities in Jasper's marketing copilot."},
  {"slug":"stable-diffusion","website_url":"https://stability.ai","pricing_model":"open_source","pricing_details":"Open-weight SD 3.5 and community models are free to self-host; Stability API uses credit-based paid tiers for hosted inference.","tagline":"Open-weight image ecosystem plus Stability's hosted SD 3.5 API.","description":"Stable Diffusion is the open image generation ecosystem anchored by Stability AI releases such as SD 3.5, alongside community models, LoRAs, ControlNet workflows, and local tools."}
